begin;
alter table public.exams disable trigger trg_exams_sync_bank;
do $do$ declare r jsonb; e jsonb; h text; begin
  for r in select * from jsonb_array_elements($j$[{"id":1540528,"nq":{"form":"bai_tap","type":"true_false","topic":"Chuyển động của điện tích trong điện trường đều","question":"Một hạt bụi tích điện có khối lượng 0,006 (mg) lơ lửng trong điện trường đều với vectơ cường độ điện trường hướng từ trên xuống dưới và có độ lớn  $3.10^3$  (V/m). Biết gia tốc rơi tự do  $g=10m/s^2.$","difficulty":"kho","statements":[{"text":"Trọng lực của hạt bụi có độ lớn bằng 6.10<sup>−4</sup> N.","answer":false},{"text":"Lực điện tác dụng vào hạt bụi có phương thẳng đứng, chiều hướng xuống.","answer":false},{"text":"Hạt bụi mang điện tích q = - 2.10<sup>−8</sup> C.","answer":false},{"text":"Lực điện có độ lớn bằng độ lớn trọng lực của hạt bụi.","answer":true}],"explanation":"<p class=\"text-base leading-relaxed my-2\">Khối lượng $m=0{,}006\\ mg=6\\cdot10^{-9}\\ kg$; trọng lực $P=mg=6\\cdot10^{-8}\\ N$.</p><p class=\"text-base leading-relaxed my-2\">a) Sai. Trọng lực là $6\\cdot10^{-8}\\ N$, không phải $6\\cdot10^{-4}\\ N$.</p><p class=\"text-base leading-relaxed my-2\">b) Sai. Hạt lơ lửng nên lực điện cân bằng trọng lực, phải hướng lên.</p><p class=\"text-base leading-relaxed my-2\">c) Sai. Lực điện hướng lên còn $\\vec{E}$ hướng xuống nên $q\\lt0$ với độ lớn $|q|=\\dfrac{P}{E}=\\dfrac{6\\cdot10^{-8}}{3\\cdot10^3}=2\\cdot10^{-11}\\ C$, không phải $2\\cdot10^{-8}$ C.</p><p class=\"text-base leading-relaxed my-2\">d) Đúng. Hạt lơ lửng nên lực điện có độ lớn bằng trọng lực.</p>","difficultySource":"ai"},"ex":[{"exam":831,"idx":13,"el":{"form":"bai_tap","type":"true_false","topic":"Chuyển động của điện tích trong điện trường đều","question":"Một hạt bụi tích điện có khối lượng 0,006 (mg) lơ lửng trong điện trường đều với vectơ cường độ điện trường hướng từ trên xuống dưới và có độ lớn  $3.10^3$  (V/m). Biết gia tốc rơi tự do  $g=10m/s^2.$","difficulty":"kho","statements":[{"text":"Trọng lực của hạt bụi có độ lớn bằng 6.10<sup>−4</sup> N.","answer":false},{"text":"Lực điện tác dụng vào hạt bụi có phương thẳng đứng, chiều hướng xuống.","answer":false},{"text":"Hạt bụi mang điện tích q = - 2.10<sup>−8</sup> C.","answer":false},{"text":"Lực điện có độ lớn bằng độ lớn trọng lực của hạt bụi.","answer":true}],"explanation":"","difficultySource":"ai"}}]}]$j$::jsonb) loop
    h := public.question_content_hash(r->'nq');
    if exists (select 1 from public.question_bank where content_hash = h and id <> (r->>'id')::bigint) then raise notice 'TRUNG %', r->>'id'; continue; end if;
    update public.question_bank set question = r->'nq', content_hash = h, updated_at = now() where id = (r->>'id')::bigint;
    for e in select * from jsonb_array_elements(r->'ex') loop
      update public.exams set questions = jsonb_set(questions, array[e->>'idx'], e->'el') where id = (e->>'exam')::bigint;
    end loop;
  end loop;
end $do$;
alter table public.exams enable trigger trg_exams_sync_bank;
commit;
